 void appGrid(boolean preview){PackageManager pm=getPackageManager();java.util.LinkedHashMap<String,ResolveInfo> found=new java.util.LinkedHashMap<>();for(String cat:new String[]{Intent.CATEGORY_LEANBACK_LAUNCHER,Intent.CATEGORY_LAUNCHER}){Intent q=new Intent(Intent.ACTION_MAIN);q.addCategory(cat);for(ResolveInfo r:pm.queryIntentActivities(q,0)){String pkg=r.activityInfo.packageName;if(!pkg.equals(getPackageName())&&!found.containsKey(pkg))found.put(pkg,r);}}if(found.isEmpty()){tile(content,"Uygulama bulunamadı","Yüklü uygulama listesi boş",()->{});return;}int cols=wide?7:3;LinearLayout line=null;int index=0;for(ResolveInfo r:found.values()){if(preview&&index>=7)break;if(index%cols==0){line=new LinearLayout(this);line.setOrientation(0);content.addView(line);}final String pkg=r.activityInfo.packageName;LinearLayout cell=column();cell.setGravity(Gravity.CENTER);cell.setPadding(dp(5),dp(5),dp(5),dp(5));cell.setBackground(shape(0xff18244a,0xff33205d,15));cell.setFocusable(true);cell.setOnFocusChangeListener((v,focus)->cell.setBackground(focus?shape(0xff7336df,0xffad4ded,15):shape(0xff18244a,0xff33205d,15)));ImageView icon=new ImageView(this);try{icon.setImageDrawable(r.loadIcon(pm));}catch(Exception ignored){}cell.addView(icon,new LinearLayout.LayoutParams(dp(32),dp(32)));TextView label=text(r.loadLabel(pm).toString(),12,true);label.setGravity(Gravity.CENTER);label.setMaxLines(1);label.setEllipsize(android.text.TextUtils.TruncateAt.END);cell.addView(label);cell.setOnClickListener(v->launch(pkg));cell.setOnLongClickListener(v->{toggleFavorite(pkg,r.loadLabel(pm).toString());return true;});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(72),1);lp.setMargins(dp(4),dp(5),dp(4),dp(5));line.addView(cell,lp);index++;}if(line!=null&&index%cols!=0){for(int i=index%cols;i<cols;i++){line.addView(new Space(this),new LinearLayout.LayoutParams(0,dp(1),1));}}}
 void appList(boolean preview){PackageManager pm=getPackageManager();HashSet<String> seen=new HashSet<>();int count=0;for(String category:new String[]{Intent.CATEGORY_LEANBACK_LAUNCHER,Intent.CATEGORY_LAUNCHER}){Intent q=new Intent(Intent.ACTION_MAIN);q.addCategory(category);for(ResolveInfo r:pm.queryIntentActivities(q,0)){String id=r.activityInfo.packageName+"/"+r.activityInfo.name;if(!seen.add(id)||r.activityInfo.packageName.equals(getPackageName()))continue;final String pkg=r.activityInfo.packageName;tile(content,"▣ "+r.loadLabel(pm),"Uygulamayı aç",()->launch(pkg));if(preview&&++count>=6)return;}}if(count==0)tile(content,"Uygulama bulunamadı","Cihaz uygulamaları listelenemiyor",()->{});}
 void searchApps(){EditText field=new EditText(this);field.setSingleLine(true);field.setHint("Uygulama adı");new AlertDialog.Builder(this).setTitle("Uygulama Ara").setView(field).setPositiveButton("Ara",(d,w)->showSearch(field.getText().toString())).setNegativeButton("İptal",null).show();}
 void showSearch(String query){PackageManager pm=getPackageManager();LinkedHashMap<String,String> matches=new LinkedHashMap<>();for(String cat:new String[]{Intent.CATEGORY_LEANBACK_LAUNCHER,Intent.CATEGORY_LAUNCHER}){Intent intent=new Intent(Intent.ACTION_MAIN);intent.addCategory(cat);for(ResolveInfo r:pm.queryIntentActivities(intent,0)){String pkg=r.activityInfo.packageName;String label=r.loadLabel(pm).toString();if(!pkg.equals(getPackageName())&&label.toLowerCase(java.util.Locale.ROOT).contains(query.toLowerCase(java.util.Locale.ROOT)))matches.put(pkg,label);}}if(matches.isEmpty()){alert("Eşleşen uygulama bulunamadı");return;}String[] pkgs=matches.keySet().toArray(new String[0]);String[] labels=matches.values().toArray(new String[0]);new AlertDialog.Builder(this).setTitle("Arama Sonuçları").setItems(labels,(d,which)->launch(pkgs[which])).setNegativeButton("Kapat",null).show();}
 void toggleFavorite(String pkg,String label){android.content.SharedPreferences prefs=getSharedPreferences("tvplus_favorites",0);boolean was=prefs.getBoolean(pkg,false);prefs.edit().putBoolean(pkg,!was).putString(pkg+"_label",label).apply();android.widget.Toast.makeText(this,was?"Favorilerden çıkarıldı":"Favorilere eklendi",android.widget.Toast.LENGTH_SHORT).show();}
 void favorites(){android.content.SharedPreferences prefs=getSharedPreferences("tvplus_favorites",0);ArrayList<String> packages=new ArrayList<>(),labels=new ArrayList<>();for(java.util.Map.Entry<String,?> e:prefs.getAll().entrySet()){String pkg=e.getKey();if(pkg.endsWith("_label")||!(e.getValue() instanceof Boolean)||!((Boolean)e.getValue()))continue;packages.add(pkg);labels.add(prefs.getString(pkg+"_label",pkg));}if(packages.isEmpty()){alert("Henüz favori yok. Uygulama ikonuna uzun basarak favorilere ekleyebilirsin.");return;}new AlertDialog.Builder(this).setTitle("★ Favoriler").setItems(labels.toArray(new String[0]),(d,i)->launch(packages.get(i))).setNeutralButton("Düzenle",(d,w)->new AlertDialog.Builder(this).setTitle("Favorilerden çıkar").setItems(labels.toArray(new String[0]),(dialog,i)->{getSharedPreferences("tvplus_favorites",0).edit().putBoolean(packages.get(i),false).apply();}).show()).setNegativeButton("Kapat",null).show();}
