 void displayDiagnostics(){android.util.DisplayMetrics m=getResources().getDisplayMetrics();android.view.Display d=getWindowManager().getDefaultDisplay();android.graphics.Point size=new android.graphics.Point();d.getRealSize(size);String info="Fiziksel ekran: "+size.x+" × "+size.y+"\\nUygulama alanı: "+m.widthPixels+" × "+m.heightPixels+"\\nYoğunluk: "+m.densityDpi+" DPI\\nÖlçek: "+String.format(java.util.Locale.US,"%.2f",m.density)+"\\nYenileme: "+String.format(java.util.Locale.US,"%.1f Hz",d.getRefreshRate())+"\\nYön: "+(getResources().getConfiguration().orientation==2?"Yatay":"Dikey");new AlertDialog.Builder(this).setTitle("Ekran Laboratuvarı").setMessage(info).setPositiveButton("Ekran Ayarları",(x,y)->setting(Settings.ACTION_DISPLAY_SETTINGS)).setNegativeButton("Kapat",null).show();}
 void powerDiagnostics(){android.os.BatteryManager bm=(android.os.BatteryManager)getSystemService(BATTERY_SERVICE);int level=bm.getIntProperty(android.os.BatteryManager.BATTERY_PROPERTY_CAPACITY);Intent battery=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));int status=battery==null?-1:battery.getIntExtra(android.os.BatteryManager.EXTRA_STATUS,-1);boolean charging=status==android.os.BatteryManager.BATTERY_STATUS_CHARGING||status==android.os.BatteryManager.BATTERY_STATUS_FULL;long up=android.os.SystemClock.elapsedRealtime()/60000;String info="Pil: "+(level>=0?level+"%":"Bu cihazda raporlanmıyor")+"\\nŞarj durumu: "+(battery==null?"Bilinmiyor":charging?"Şarj oluyor / dolu":"Şarj olmuyor")+"\\nAçık kalma süresi: "+(up/60)+" saat "+(up%60)+" dakika\\nGüç yönetimi Android tarafından kontrol edilir.";new AlertDialog.Builder(this).setTitle("Pil ve Güç").setMessage(info).setPositiveButton("Tamam",null).show();}
 void inputDiagnostics(){StringBuilder sb=new StringBuilder();int[] ids=android.view.InputDevice.getDeviceIds();for(int id:ids){android.view.InputDevice dev=android.view.InputDevice.getDevice(id);if(dev!=null){sb.append("• ").append(dev.getName()).append(" (ID ").append(id).append(")\\n");}}if(sb.length()==0)sb.append("Giriş aygıtı listelenemedi.");new AlertDialog.Builder(this).setTitle("Bağlı Giriş Aygıtları").setMessage(sb.toString()).setPositiveButton("Kumanda Testi",(d,w)->remoteTester()).setNegativeButton("Kapat",null).show();}
 android.app.Dialog remoteDialog;TextView remoteOutput;
 void remoteTester(){LinearLayout panel=column();panel.setPadding(dp(24),dp(16),dp(24),dp(16));TextView guide=text("Kumandada bir tuşa bas. Tuş kodu ve adı burada gösterilir. Geri tuşu testi kapatır.",15,false);panel.addView(guide);gap(panel,14);remoteOutput=text("Tuş bekleniyor…",20,true);panel.addView(remoteOutput);android.app.Dialog dialog=new android.app.Dialog(this);dialog.setContentView(panel);dialog.getWindow().setBackgroundDrawable(shape(0xff1d2356,0xff35216a,20));dialog.setOnKeyListener((di,key,event)->{if(event.getAction()!=android.view.KeyEvent.ACTION_DOWN)return false;if(key==android.view.KeyEvent.KEYCODE_BACK){di.dismiss();return true;}remoteOutput.setText("Kod: "+key+"\\nTuş: "+android.view.KeyEvent.keyCodeToString(key)+"\\nTekrar: "+event.getRepeatCount());return true;});dialog.show();}
