 void timerDialog(boolean sleep){final String[] options={"5 dakika","15 dakika","30 dakika","60 dakika"};final int[] minutes={5,15,30,60};new AlertDialog.Builder(this).setTitle(sleep?"Uyku Zamanlayıcısı":"Odak Zamanlayıcısı").setItems(options,(d,which)->startCountdown(minutes[which],sleep)).setNegativeButton("İptal",null).show();}
 android.os.Handler countdownHandler=new android.os.Handler(android.os.Looper.getMainLooper());Runnable countdownTask;long countdownEnd;boolean countdownSleep;
 void startCountdown(int minutes,boolean sleep){if(countdownTask!=null)countdownHandler.removeCallbacks(countdownTask);countdownEnd=android.os.SystemClock.elapsedRealtime()+minutes*60000L;countdownSleep=sleep;countdownTask=()->{long remaining=countdownEnd-android.os.SystemClock.elapsedRealtime();if(remaining<=0){countdownTask=null;if(countdownSleep){android.widget.Toast.makeText(this,"TV+ uyku zamanlayıcısı tamamlandı",android.widget.Toast.LENGTH_LONG).show();finish();}else new AlertDialog.Builder(this).setTitle("Süre doldu").setMessage("Odak zamanlayıcısı tamamlandı.").setPositiveButton("Tamam",null).show();}else countdownHandler.postDelayed(countdownTask,Math.min(remaining,1000));};countdownHandler.post(countdownTask);android.widget.Toast.makeText(this,"Zamanlayıcı başladı: "+minutes+" dakika",android.widget.Toast.LENGTH_LONG).show();}
 void deviceInfo(){android.app.ActivityManager am=(android.app.ActivityManager)getSystemService(ACTIVITY_SERVICE);android.app.ActivityManager.MemoryInfo mi=new android.app.ActivityManager.MemoryInfo();am.getMemoryInfo(mi);String info="Android: "+android.os.Build.VERSION.RELEASE+" (API "+android.os.Build.VERSION.SDK_INT+")\\nCihaz: "+android.os.Build.MANUFACTURER+" "+android.os.Build.MODEL+"\\nToplam RAM: "+String.format(java.util.Locale.US,"%.1f GB",mi.totalMem/1e9)+"\\nKullanılabilir RAM: "+String.format(java.util.Locale.US,"%.1f GB",mi.availMem/1e9)+"\\nEkran: "+getResources().getDisplayMetrics().widthPixels+" × "+getResources().getDisplayMetrics().heightPixels;new AlertDialog.Builder(this).setTitle("TV+ Cihaz Bilgisi").setMessage(info).setPositiveButton("Tamam",null).show();}
 void storageInfo(){android.os.StatFs fs=new android.os.StatFs(android.os.Environment.getDataDirectory().getPath());long total=fs.getTotalBytes(),free=fs.getAvailableBytes();String s=String.format(java.util.Locale.US,"Toplam: %.2f GB\\nKullanılan: %.2f GB\\nBoş: %.2f GB",total/1e9,(total-free)/1e9,free/1e9);new AlertDialog.Builder(this).setTitle("Depolama Analizi").setMessage(s).setPositiveButton("Dosyaları Aç",(d,w)->tree()).setNegativeButton("Kapat",null).show();}
 void networkInfo(){StringBuilder s=new StringBuilder();android.net.ConnectivityManager cm=(android.net.ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);android.net.Network n=cm.getActiveNetwork();android.net.NetworkCapabilities caps=n==null?null:cm.getNetworkCapabilities(n);s.append("Bağlantı: ");if(caps==null)s.append("Aktif ağ yok");else if(caps.hasTransport(android.net.NetworkCapabilities.TRANSPORT_WIFI))s.append("Wi-Fi");else if(caps.hasTransport(android.net.NetworkCapabilities.TRANSPORT_ETHERNET))s.append("Ethernet");else s.append("Diğer");s.append("\\nİnternet doğrulandı: ").append(caps!=null&&caps.hasCapability(android.net.NetworkCapabilities.NET_CAPABILITY_VALIDATED)?"Evet":"Hayır / bilinmiyor");if(n!=null){android.net.LinkProperties lp=cm.getLinkProperties(n);if(lp!=null){for(android.net.LinkAddress address:lp.getLinkAddresses()){java.net.InetAddress ip=address.getAddress();if(ip instanceof java.net.Inet4Address)s.append("\\nYerel IPv4: ").append(ip.getHostAddress());}s.append("\\nDNS: ");for(java.net.InetAddress dns:lp.getDnsServers())s.append(dns.getHostAddress()).append(" ");}}new AlertDialog.Builder(this).setTitle("Ağ Teşhisi").setMessage(s.toString()).setPositiveButton("Ağ Ayarları",(d,w)->setting(Settings.ACTION_WIRELESS_SETTINGS)).setNegativeButton("Kapat",null).show();}
