 void sound(){heading("Ses Kontrolü");android.media.AudioManager a=(android.media.AudioManager)getSystemService(AUDIO_SERVICE);int max=a.getStreamMaxVolume(3);SeekBar bar=new SeekBar(this);bar.setMax(max);bar.setProgress(a.getStreamVolume(3));bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int p,boolean user){if(user)a.setStreamVolume(3,p,0);}});content.addView(bar);tile(content,"＋ Sesi Artır",null,()->{a.adjustStreamVolume(3,1,0);bar.setProgress(a.getStreamVolume(3));});tile(content,"－ Sesi Azalt",null,()->{a.adjustStreamVolume(3,-1,0);bar.setProgress(a.getStreamVolume(3));});tile(content,"◉ Sessize Al / Sesi Aç",null,()->{a.adjustStreamVolume(3,android.media.AudioManager.ADJUST_TOGGLE_MUTE,android.media.AudioManager.FLAG_SHOW_UI);bar.setProgress(a.getStreamVolume(3));});}
