 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null)return;Uri uri=data.getData();if(req==931){try{Intent send=new Intent(Intent.ACTION_SEND);String mime=getContentResolver().getType(uri);send.setType(mime==null?"application/octet-stream":mime);send.putExtra(Intent.EXTRA_STREAM,uri);send.setClipData(ClipData.newUri(getContentResolver(),"TV+ Dosya",uri));send.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(send,"Quick Share veya başka uygulamayla paylaş"));}catch(Exception e){alert("Paylaşım başarısız: "+e.getMessage());}return;}if(req==20){alert("Klasör seçildi: "+uri);return;}try{if(req==11||req==12){Intent player=new Intent(this,tv.plus.pro.unified.VideoPlayerActivity.class);player.setDataAndType(uri,req==11?"image/*":"video/*");player.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(player);return;}Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(uri,getContentResolver().getType(uri));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(i);}catch(Exception e){alert("Dosya açılamadı: "+e.getMessage());}}
 void alert(String msg){new AlertDialog.Builder(this).setMessage(msg).setPositiveButton("Tamam",null).show();}
 @Override public void onCreate(Bundle b){super.onCreate(b);setVolumeControlStream(android.media.AudioManager.STREAM_MUSIC);applyAwake();render("home");}
 @Override public boolean onKeyDown(int keyCode,android.view.KeyEvent event){if(keyCode==android.view.KeyEvent.KEYCODE_MENU||keyCode==android.view.KeyEvent.KEYCODE_INFO){remoteMenu();return true;}if(keyCode==android.view.KeyEvent.KEYCODE_VOLUME_UP||keyCode==android.view.KeyEvent.KEYCODE_VOLUME_DOWN||keyCode==android.view.KeyEvent.KEYCODE_VOLUME_MUTE){return super.onKeyDown(keyCode,event);}return super.onKeyDown(keyCode,event);}
